#include <iostream>
#include <optional>
#include <sstream>
#include <string>

std::optional<int> parse_count(const std::string& text) {
    std::istringstream input{text};
    int count;
    if (!(input >> count) || count < 0) return std::nullopt;
    input >> std::ws;
    if (!input.eof()) return std::nullopt;
    return count;
}

int main() {
    std::cout << parse_count(" 42 ").value_or(-1) << '\n';
}

#include <iostream>
#include <string>
#include <utility>

class Book {
public:
    explicit Book(std::string title) : title_{std::move(title)} {}
    void rename(std::string title) { title_ = std::move(title); }
    const std::string& title() const { return title_; }
private:
    std::string title_;
};

int main() {
    Book original{"Field notes"};
    Book copy = original;
    copy.rename("Lab notes");
    std::cout << original.title() << " | " << copy.title() << '\n';
}

#include <iostream>
#include <string>
#include <string_view>

static std::string_view category(std::string_view record) {
    return record.substr(0, record.find(':'));
}

int main() {
    const std::string record{"math:42"};
    const auto view = category(record);
    std::cout << view << '\n';
}

#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> readings{8, -1, -2, 4, 0};
    const auto tail = std::remove_if(readings.begin(), readings.end(),
                                     [](int value) { return value < 0; });
