}

#include <iostream>
#include <string>

template <typename T>
T earlier(const T& left, const T& right) {
    return right < left ? right : left;
}

int main() {
    std::cout << earlier(9, 4) << '\n';
    std::cout << earlier(std::string{"Zinc"}, std::string{"Copper"}) << '\n';
}

