#include <algorithm>
#include <iostream>
#include <string>
#include <tuple>
#include <vector>

struct Report { int level; std::string label; };

int main() {
    std::vector<Report> reports{{2, "mint"}, {1, "zinc"}, {1, "copper"}};
    std::sort(reports.begin(), reports.end(), [](const Report& a, const Report& b) {
        return std::tie(a.level, a.label) < std::tie(b.level, b.label);
    });
    for (const auto& item : reports) std::cout << item.label << '\n';
}

#include <initializer_list>
#include <iostream>
#include <string>
#include <variant>

using Reading = std::variant<int, std::string>;

static Reading validate(int value) {
    if (value < 0 || value > 100) return std::string{"out of range"};
    return value;
}

int main() {
    for (int sample : {42, 101}) {
        const auto result = validate(sample);
        if (const auto* score = std::get_if<int>(&result)) {
            std::cout << "score=" << *score << '\n';
        } else if (const auto* error = std::get_if<std::string>(&result)) {
            std::cout << *error << '\n';
        }
    }
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> titles{"Zoology", "Algebra", "Networks"};
    std::sort(titles.begin(), titles.end());
    const std::string query{"Networks"};
    const auto position = std::lower_bound(titles.begin(), titles.end(), query);
    if (position != titles.end() && *position == query) {
        std::cout << "found: " << *position << '\n';
    } else {
        std::cout << "not found\n";
    }
}
